        {
          "id": "root",
          "type": "container",
          "layout": "vertical",
          "children": [
            {
              "id": "introduction",
              "type": "text",
              "content": "This guide will help you change the SSID and WPA2 password for your Linksys EA8300 router."
            },
            {
              "id": "assumptions",
              "type": "text",
              "content": "Assumptions:\n- You are connected to your Linksys EA8300 router.\n- You know the current administrative password."
            },
            {
              "id": "default_info",
              "type": "text",
              "content": "Default Router Access Information:\n- Local IP Address: 192.168.1.1\n- Username: admin\n- Password: admin or password"
            },
            {
              "id": "step1",
              "type": "heading",
              "level": 2,
              "content": "1. Access Your Router's Web Interface"
            },
            {
              "id": "step1_text",
              "type": "text",
              "content": "Open a web browser and type 192.168.1.1 in the address bar."
            },
            {
              "id": "step2",
              "type": "heading",
              "level": 2,
              "content": "2. Log In to Your Router"
            },
            {
              "id": "step2_text",
              "type": "text",
              "content": "Enter Username (admin) and Password."
            },
            {
              "id": "step3",
              "type": "heading",
              "level": 2,
              "content": "3. Navigate to Wireless Settings"
            },
            {
              "id": "step3_text",
              "type": "text",
              "content": "Look for sections like 'Wi-Fi Settings' or 'Wireless'."
            },
            {
              "id": "step4",
              "type": "heading",
              "level": 2,
              "content": "4. Change the Wi-Fi Network Name (SSID)"
            },
            {
              "id": "step4_text",
              "type": "text",
              "content": "Locate the 'Network Name (SSID)' field for both 2.4 GHz and 5 GHz bands and enter your desired new name."
            },
            {
              "id": "step5",
              "type": "heading",
              "level": 2,
              "content": "5. Change the Wi-Fi Password (WPA2 Security Key)"
            },
            {
              "id": "step5_text",
              "type": "text",
              "content": "Ensure 'Security Mode' is set to 'WPA2 Personal' or 'WPA2/WPA3 Personal'. Enter your new password."
            },
            {
              "id": "step6",
              "type": "heading",
              "level": 2,
              "content": "6. Save Your Changes"
            },
            {
              "id": "step6_text",
              "type": "text",
              "content": "Click 'Apply', 'Save', or 'OK'."
            },
            {
              "id": "step7",
              "type": "heading",
              "level": 2,
              "content": "7. Reconnect Your Devices"
            },
            {
              "id": "step7_text",
              "type": "text",
              "content": "Forget the old Wi-Fi network on each device and connect to the new one with the new password."
            },
            {
              "id": "important_note",
              "type": "text",
              "content": "Remember your new SSID and Wi-Fi password."
            }
          ]
        }
      ]
    }
